    .completed(price: 1250),
    .cancelledByDriver(reason: "сломалась машина"),
    .completed(price: 380)
]
for ride in evening {
    print("Оплачено: \(paidAmount(for: ride)) руб., бонусов: \(bonusPoints(for: ride))")
}
print(apologyText(for: evening[1]) ?? "Извиняться не за что")

